<section class="dashboard-hero dashboard-hero-compact"><div class="container dashboard-hero-inner"><div><span class="eyebrow">Community oversight</span><h1>People & <em>accounts.</em></h1><p>Search, filter and manage DonorNexa access.</p></div><a class="button button-light button-small" href="<?= e(url('export', ['type' => 'donors'])) ?>">Export donors ↓</a></div></section>
