    <form class="table-filters" method="get" action="<?= e(APP_URL) ?>/index.php"><input type="hidden" name="page" value="users"><label class="sr-only" for="people-search">Search name or email</label><input id="people-search" name="q" value="<?= e($search) ?>" placeholder="Search name or email"><label class="sr-only" for="people-role">Filter role</label><select id="people-role" name="role"><option value="">All roles</option><?php foreach (['donor', 'hospital', 'admin'] as $value): ?><option value="<?= e($value) ?>" <?= $role === $value ? 'selected' : '' ?>><?= e(ucfirst($value)) ?></option><?php endforeach; ?></select><label class="sr-only" for="people-sort">Sort by</label><select id="people-sort" name="sort"><option value="joined" <?= $sort === 'joined' ? 'selected' : '' ?>>Date joined</option><option value="name" <?= $sort === 'name' ? 'selected' : '' ?>>Name</option><option value="status" <?= $sort === 'status' ? 'selected' : '' ?>>Status</option></select><label class="sr-only" for="people-direction">Sort direction</label><select id="people-direction" name="direction"><option value="DESC" <?= $direction === 'DESC' ? 'selected' : '' ?>>Descending</option><option value="ASC" <?= $direction === 'ASC' ? 'selected' : '' ?>>Ascending</option></select><button class="button button-outline button-small" type="submit">Apply</button></form>
